package com.wildfire.neoforge.appearance;
import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.components.Button;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;import java.util.*;
public final class StreamCenterScreen extends Screen {
    private final Screen parent;private int left,top,w,h;private List<StreamNoticeClient.Entry> rows=List.of();
    public StreamCenterScreen(Screen parent){super(Component.literal("Активные стримы"));this.parent=parent;}
    @Override protected void init(){rows=StreamNoticeClient.active();w=Math.min(620,width-16);h=Math.min(380,height-16);left=(width-w)/2;top=(height-h)/2;addRenderableWidget(com.wildfire.gui.FlatButtons.builder(Component.literal("✕"),b->onClose()).bounds(left+w-29,top+7,21,20).build());int y=top+48;for(var e:rows.stream().limit(4).toList()){var url=e.url();addRenderableWidget(com.wildfire.gui.FlatButtons.builder(Component.literal("Смотреть"),b->open(url)).bounds(left+w-112,y+35,92,22).build());y+=72;}}
    private void open(String url){try{java.awt.Desktop.getDesktop().browse(java.net.URI.create(url));}catch(Exception ignored){}}
    private void label(GuiGraphicsExtractor g,String s,int x,int y,int max,int color){g.text(font,font.plainSubstrByWidth(s,Math.max(1,max)),x,y,color,false);}
    @Override public void extractRenderState(GuiGraphicsExtractor g,int mx,int my,float delta){g.fill(0,0,width,height,0xA0000000);com.wildfire.gui.FlatButtons.plate(g,left,top,w,h,true,false,false,com.wildfire.gui.UiTheme.ACCENT);String head="Активные стримы";g.text(font,head,left+(w-font.width(head))/2,top+14,com.wildfire.gui.UiTheme.TEXT,false);if(rows.isEmpty())label(g,"Сейчас никто не стримит",left+20,top+58,w-40,com.wildfire.gui.UiTheme.MUTED);int y=top+48;for(var e:rows.stream().limit(4).toList()){com.wildfire.gui.FlatButtons.plate(g,left+14,y,w-28,64,true,false,false,0xFFFF5264);StreamPreviewCache.draw(g,e.preview(),left+20,y+6,88,50);label(g,e.streamer()+" · "+e.platform(),left+118,y+8,w-258,com.wildfire.gui.UiTheme.ACCENT);label(g,e.title(),left+118,y+25,w-258,com.wildfire.gui.UiTheme.TEXT);label(g,e.viewers()>=0?e.viewers()+" зрителей":"В эфире",left+118,y+43,w-258,com.wildfire.gui.UiTheme.MUTED);y+=72;}super.extractRenderState(g,mx,my,delta);}
    @Override public void onClose(){minecraft.gui.setScreen(parent);}@Override public boolean isPauseScreen(){return false;}
}
